  "implementation": "def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    required_symbols = set(payload['required_symbols'])
    node_map = {node['id']: node for node in nodes}
    children = {node['id']: [] for node in nodes}
    for node in nodes:
        if node['parent'] is not None:
            children[node['parent']].append(node['id'])
    retained = set(node['id'] for node in nodes)
    candidates = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removal_order = []
    for node in candidates:
        nid = node['id']
        if nid not in retained:
            continue
        if node['symbol'] in required_symbols:
            continue
        if not node['removable']:
            continue
        if node['parent'] is None:
            continue
        if any(child_id in retained for child_id in children[nid]):
            continue
        retained.remove(nid)
        removal_order.append(nid)
    return {
        'retained': sorted(retained),
        'removal_order': removal_order
    }"
